+/**
+ * Authenticated data boundary for Twyne's CLI and local MCP server.
+ *
+ * Browser users mint personal tokens through the public functions at the top
+ * of this module. The external HTTP route hashes a presented bearer token,
+ * resolves it through `authenticate`, then calls only the internal functions
+ * below with the verified owner id. Raw tokens never enter Convex storage.
+ */
+import { v } from "convex/values";
+import {
+  internalMutation,
+  internalQuery,
+  mutation,
+  query,
+} from "./_generated/server";
+
+const MAX_TOKEN_NAME_LENGTH = 80;
+const MAX_FOLIO_NAME_LENGTH = 240;
+const MAX_FOLIOS_PER_ACCOUNT = 500;
+const MAX_SEARCH_RESULTS = 50;
+
+const folioType = v.union(
+  v.literal("draft"),
+  v.literal("notes"),
+  v.literal("outline"),
+);
+
+const folioInput = v.object({
+  id: v.optional(v.string()),
+  name: v.string(),
+  type: v.optional(folioType),
+  createdAt: v.optional(v.number()),
+  updatedAt: v.optional(v.number()),
+  layout: v.optional(v.any()),
+  header: v.optional(v.string()),
+  footer: v.optional(v.string()),
+});
+
+const includeValue = v.union(
+  v.literal("content"),
+  v.literal("brief"),
+  v.literal("feedback"),
+  v.literal("rubric"),
+  v.literal("suggestions"),
+  v.literal("citations"),
+);
+
+async function requireIdentity(ctx: {
+  auth: { getUserIdentity: () => Promise<{ tokenIdentifier: string } | null> };
+}): Promise<string> {
+  const identity = await ctx.auth.getUserIdentity();
+  if (!identity) throw new Error("Not signed in");
+  return identity.tokenIdentifier;
+}
+
+function normalizeTokenName(name: string): string {
+  const normalized = name.trim();
+  if (!normalized) throw new Error("Token name is required");
+  if (normalized.length > MAX_TOKEN_NAME_LENGTH) {
+    throw new Error(`Token name must be ${MAX_TOKEN_NAME_LENGTH} characters or fewer`);
+  }
+  return normalized;
+}
+
+async function sha256(value: string): Promise<string> {
+  const digest = await crypto.subtle.digest(
+    "SHA-256",
+    new TextEncoder().encode(value),
+  );
+  return Array.from(new Uint8Array(digest), (byte) =>
+    byte.toString(16).padStart(2, "0"),
+  ).join("");
+}
+
+function newToken(): string {
+  const bytes = crypto.getRandomValues(new Uint8Array(32));
+  const secret = Array.from(bytes, (byte) =>
+    byte.toString(16).padStart(2, "0"),
+  ).join("");
+  return `twyne_pat_${secret}`;
+}
+
+export const createToken = mutation({
+  args: { name: v.string() },
+  returns: v.object({
+    id: v.id("integrationTokens"),
+    name: v.string(),
+    prefix: v.string(),
+    token: v.string(),
+    createdAt: v.number(),
+  }),
+  handler: async (ctx, { name }) => {
+    const userId = await requireIdentity(ctx);
+    const normalizedName = normalizeTokenName(name);
+    const token = newToken();
+    const tokenHash = await sha256(token);
+    const prefix = token.slice(0, 18);
+    const createdAt = Date.now();
+    const id = await ctx.db.insert("integrationTokens", {
+      userId,
+      tokenHash,
+      prefix,
+      name: normalizedName,
+      createdAt,
+    });
+    return { id, name: normalizedName, prefix, token, createdAt };
+  },
+});
+
+export const listTokens = query({
+  args: {},
+  returns: v.array(
+    v.object({
+      id: v.id("integrationTokens"),
+      name: v.string(),
+      prefix: v.string(),
+      createdAt: v.number(),
+    }),
+  ),
+  handler: async (ctx) => {
+    const userId = await requireIdentity(ctx);
+    const rows = await ctx.db
+      .query("integrationTokens")
+      .withIndex("by_userId", (q) => q.eq("userId", userId))
+      .order("desc")
+      .take(50);
+    return rows.map((row) => ({
+      id: row._id,
+      name: row.name,
+      prefix: row.prefix,
+      createdAt: row.createdAt,
+    }));
+  },
+});
+
+export const revokeToken = mutation({
+  args: { id: v.id("integrationTokens") },
+  returns: v.boolean(),
+  handler: async (ctx, { id }) => {
+    const userId = await requireIdentity(ctx);
+    const token = await ctx.db.get("integrationTokens", id);
+    if (!token || token.userId !== userId) return false;
+    await ctx.db.delete("integrationTokens", id);
+    return true;
+  },
+});
+
+export const authenticate = internalQuery({
+  args: { tokenHash: v.string() },
+  returns: v.union(
+    v.null(),
+    v.object({ userId: v.string(), tokenId: v.id("integrationTokens") }),
+  ),
+  handler: async (ctx, { tokenHash }) => {
+    const token = await ctx.db
+      .query("integrationTokens")
+      .withIndex("by_tokenHash", (q) => q.eq("tokenHash", tokenHash))
+      .unique();
+    return token ? { userId: token.userId, tokenId: token._id } : null;
+  },
+});
+
+export const listFolios = internalQuery({
+  args: { userId: v.string() },
+  returns: v.array(v.any()),
+  handler: async (ctx, { userId }) => {
+    const row = await ctx.db
+      .query("folios")
+      .withIndex("by_userId", (q) => q.eq("userId", userId))
+      .first();
+    return Array.isArray(row?.folios) ? row.folios : [];
+  },
+});
+
+export const getFolio = internalQuery({
+  args: {
+    userId: v.string(),
+    folioId: v.string(),
+    include: v.array(includeValue),
+  },
+  returns: v.any(),
+  handler: async (ctx, { userId, folioId, include }) => {
+    const foliosRow = await ctx.db
+      .query("folios")
+      .withIndex("by_userId", (q) => q.eq("userId", userId))
+      .first();
+    const folio = (foliosRow?.folios ?? []).find(
+      (candidate: { id?: unknown }) => candidate?.id === folioId,
+    );
+    if (!folio) return null;
+
+    const wanted = new Set(include);
+    const bundle: Record<string, unknown> = { folio };
+    if (wanted.has("content")) {
+      const row = await ctx.db
+        .query("folioContent")
+        .withIndex("by_userId_folioId", (q) =>
+          q.eq("userId", userId).eq("folioId", folioId),
+        )
+        .first();
+      bundle.html = row?.html ?? "";
+      bundle.contentUpdatedAt = row?.updatedAt ?? null;
+    }
+    if (wanted.has("brief")) {
+      const row = await ctx.db
+        .query("briefs")
+        .withIndex("by_userId_folioId", (q) =>
+          q.eq("userId", userId).eq("folioId", folioId),
+        )
+        .first();
+      bundle.brief = row?.brief ?? null;
+    }
+    if (wanted.has("feedback")) {
+      const [notes, replies] = await Promise.all([
+        ctx.db
+          .query("personaNotes")
+          .withIndex("by_userId_folioId", (q) =>
+            q.eq("userId", userId).eq("folioId", folioId),
+          )
+          .collect(),
+        ctx.db
+          .query("personaReplies")
+          .withIndex("by_userId_folioId", (q) =>
+            q.eq("userId", userId).eq("folioId", folioId),
+          )
+          .collect(),
+      ]);
+      bundle.feedback = {
+        notes: notes.sort((a, b) => a.createdAt - b.createdAt),
+        replies: replies.sort((a, b) => a.createdAt - b.createdAt),
+      };
+    }
+    if (wanted.has("rubric")) {
+      const row = await ctx.db
+        .query("rubricResults")
+        .withIndex("by_userId_folioId", (q) =>
+          q.eq("userId", userId).eq("folioId", folioId),
+        )
+        .first();
+      bundle.rubric = row?.result ?? null;
+    }
+    if (wanted.has("suggestions")) {
+      bundle.suggestions = await ctx.db
+        .query("suggestions")
+        .withIndex("by_userId_folioId", (q) =>
+          q.eq("userId", userId).eq("folioId", folioId),
+        )
+        .collect();
+    }
+    if (wanted.has("citations")) {
+      const row = await ctx.db
+        .query("bibliographies")
+        .withIndex("by_userId", (q) => q.eq("userId", userId))
+        .first();
+      bundle.citations = (row?.entries ?? []).filter(
+        (entry: { folioId?: unknown }) =>
+          !entry?.folioId || entry.folioId === folioId,
+      );
+    }
+    return bundle;
+  },
+});
+
+export const putFolio = internalMutation({
+  args: {
+    userId: v.string(),
+    folio: folioInput,
+    html: v.optional(v.string()),
+    brief: v.optional(v.any()),
+  },
+  returns: v.any(),
+  handler: async (ctx, { userId, folio: input, html, brief }) => {
+    const name = input.name.trim();
+    if (!name) throw new Error("Folio name is required");
+    if (name.length > MAX_FOLIO_NAME_LENGTH) {
+      throw new Error(`Folio name must be ${MAX_FOLIO_NAME_LENGTH} characters or fewer`);
+    }
+
+    const foliosRow = await ctx.db
+      .query("folios")
+      .withIndex("by_userId", (q) => q.eq("userId", userId))
+      .first();
+    const folios = Array.isArray(foliosRow?.folios)
+      ? [...foliosRow.folios]
+      : [];
+    const id = input.id?.trim() || crypto.randomUUID();
+    const existingIndex = folios.findIndex(
+      (candidate: { id?: unknown }) => candidate?.id === id,
+    );
+    if (existingIndex < 0 && folios.length >= MAX_FOLIOS_PER_ACCOUNT) {
+      throw new Error(`An account can hold at most ${MAX_FOLIOS_PER_ACCOUNT} folios`);
+    }
+    const now = Date.now();
+    const previous = existingIndex >= 0 ? folios[existingIndex] : null;
+    const next = {
+      ...(previous ?? {}),
+      id,
+      name,
+      type: input.type ?? previous?.type ?? "draft",
+      createdAt: previous?.createdAt ?? input.createdAt ?? now,
+      updatedAt: now,
+      ...(input.layout !== undefined ? { layout: input.layout } : {}),
+      ...(input.header !== undefined ? { header: input.header } : {}),
+      ...(input.footer !== undefined ? { footer: input.footer } : {}),
+    };
+    if (existingIndex >= 0) folios[existingIndex] = next;
+    else folios.push(next);
+
+    if (foliosRow) {
+      await ctx.db.patch(foliosRow._id, { folios, updatedAt: now });
+    } else {
+      await ctx.db.insert("folios", { userId, folios, updatedAt: now });
+    }
